function Activity({data,onAction}:{data:Bundle;onAction:(p:any)=>Promise<any>}){const [submitting,setSubmitting]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(submitting)return;const fd=new FormData(e.currentTarget);const form=e.currentTarget;setSubmitting(true);try{await onAction({type:"activity",activity_type:text(fd,"activity_type"),summary:text(fd,"summary"),details:text(fd,"details"),next_action:text(fd,"next_action"),next_action_at:iso(fd.get("next_action_at"))});form.reset();}catch(error){alert(error instanceof Error?error.message:"Activity could not be saved. Your entry has been retained.");}finally{setSubmitting(false);}}return <div className="grid gap-5 xl:grid-cols-[420px_1fr]"><Card title="Log follow-up / activity"><form onSubmit={(e)=>void submit(e)} className="grid gap-3"><Field label="Method"><BmsSelect name="activity_type" className={inputClass}><option value="whatsapp">WhatsApp</option><option value="call">Phone</option><option value="email">Email</option>{data.config.modules.siteVisits&&<option value="site_visit">Site visit</option>}<option value="note">Internal note</option><option value="status">Status update</option></BmsSelect></Field><Field label="Summary"><BmsInput name="summary" required className={inputClass}/></Field><Field label="Details"><BmsTextarea name="details" className="min-h-28 w-full rounded-xl border border-black/15 p-3"/></Field><Field label="Next action"><BmsInput name="next_action" className={inputClass}/></Field><Field label="Next action due"><BmsInput name="next_action_at" type="datetime-local" className={inputClass}/></Field><BmsButton type="submit" disabled={submitting}>{submitting?"Saving activity...":"Log activity"}</BmsButton></form></Card><div className="space-y-5"><Card title="Activity timeline">{data.activities.length===0?<p className="text-sm text-black/50">No activity logged yet.</p>:<div className="space-y-3">{data.activities.map((a:any)=><div key={a.id} className="rounded-xl border border-black/10 p-4"><div className="flex flex-wrap justify-between gap-2"><b>{a.summary}</b><span className="text-xs text-black/45">{new Date(a.occurred_at).toLocaleString("en-GB")}</span></div>{a.details&&<p className="mt-2 text-sm text-black/60">{a.details}</p>}</div>)}</div>}</Card><Card title="Audit trail"><div className="space-y-2">{data.auditEvents.map((a:any)=><div key={a.id} className="flex justify-between gap-4 border-b border-black/8 py-2 text-sm"><span><b>{a.actor==="MD"?"Mark":a.actor==="JB"?"Jonathan":a.actor||"CRM user"}</b> {a.action} {a.entity_type}</span><span className="shrink-0 text-black/40">{new Date(a.created_at).toLocaleString("en-GB")}</span></div>)}</div></Card></div></div>}

function Quote({data,reference,onAction,config}:{data:Bundle;reference:string;onAction:(p:any)=>Promise<any>;config:CrmConfig}){
  const latest=data.quotes?.[0]||null;
  const [defaultLeadTime,setDefaultLeadTime]=useState("10 days"),[leadTime,setLeadTime]=useState(String(data.quotes?.[0]?.lead_time||"")),[settingsMessage,setSettingsMessage]=useState(""),[savingDefault,setSavingDefault]=useState(false);
  useEffect(()=>{let cancelled=false;fetch("/api/admin/quote-settings",{cache:"no-store"}).then(r=>r.ok?r.json():Promise.reject(new Error("Settings unavailable"))).then(x=>{if(!cancelled)setDefaultLeadTime(String(x.default_lead_time||"10 days"));}).catch(()=>{});return()=>{cancelled=true;};},[]);
  useEffect(()=>{setLeadTime(String(latest?.lead_time||defaultLeadTime));},[latest?.id,latest?.lead_time,defaultLeadTime]);
  async function saveLeadTimeDefault(){setSavingDefault(true);setSettingsMessage("");try{const r=await fetch("/api/admin/quote-settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({default_lead_time:defaultLeadTime})});const x=await r.json().catch(()=>({}));if(!r.ok)throw new Error(x.error||"Could not save");setSettingsMessage("Tenant quotation default saved.");}catch(e){setSettingsMessage(e instanceof Error?e.message:"Could not save default");}finally{setSavingDefault(false);}}
  const tidyRequest=useRef<AbortController|null>(null);
  const suggested=useMemo(()=>{const j=data.job;const types=(j.job_types||[j.job_type]).join(" and ").toLowerCase();return [`Supply and install ${types} to the agreed site.`,j.dimensions?`Approximate dimensions: ${j.dimensions}.`:"",j.material?`Manufactured in ${j.material}.`:"",(j.finishes||[]).length?`Finish: ${(j.finishes||[]).join(" and ")}${j.colour?`, ${j.colour}`:""}.`:"",j.customer_requirements||""].filter(Boolean).join("\n\n");},[data]);
  const[scope,setScope]=useState(normaliseQuoteScope(latest?.scope_text||suggested)),[exclusions,setExclusions]=useState(latest?.exclusions||""),[aiBusy,setAiBusy]=useState(false),[preRubyScope,setPreRubyScope]=useState<string|null>(null),[aiError,setAiError]=useState(""),[quoteBusy,setQuoteBusy]=useState(false),[saveResult,setSaveResult]=useState("");
  useEffect(()=>{setScope(normaliseQuoteScope(latest?.scope_text||suggested));setPreRubyScope(null);setExclusions(latest?.exclusions||"");},[latest?.id,latest?.scope_text,latest?.exclusions,suggested]);
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(quoteBusy)return;const fd=new FormData(e.currentTarget);tidyRequest.current?.abort();tidyRequest.current=null;setAiBusy(false);setAiError("");setSaveResult("");setQuoteBusy(true);try{const saved=await onAction({type:"quote",vat_rate:num(fd,"vat_rate")||0,amount:num(fd,"amount"),deposit_amount:num(fd,"deposit_amount"),lead_time:text(fd,"lead_time"),valid_until:text(fd,"valid_until"),scope_text:normaliseQuoteScope(scope),exclusions:exclusions.trim()||null});if(saved?.error)throw new Error(String(saved.error));setSaveResult("Quote saved. Open the latest version in Quote History.");}catch(err){setSaveResult("Save failed: "+(err instanceof Error?err.message:"Unknown error"));alert(err instanceof Error?err.message:"Could not save quote");}finally{setQuoteBusy(false);}}
  async function tidy(){
    if(quoteBusy)return;
    tidyRequest.current?.abort();const controller=new AbortController();tidyRequest.current=controller;
    setAiBusy(true);setAiError("");
    try{
      const original=normaliseQuoteScope(scope);
      const res=await fetch(`/api/admin/jobs/${encodeURIComponent(reference)}/ai-quote`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({scope_text:original}),signal:controller.signal});
      const body=await res.json().catch(()=>({}));
      if(!res.ok)throw new Error(body.error||"Could not tidy quotation");
      const result=normaliseQuoteScope(String(body.text||"").trim());
      const originalPrices=original.split("\n").map(x=>x.match(/£[\d,]+(?:\.\d{1,2})?/g)?.at(-1)||"").filter(Boolean);
      const newPrices=result.split("\n").map(x=>x.match(/£[\d,]+(?:\.\d{1,2})?/g)?.at(-1)||"").filter(Boolean);
      const itemNumbers=(value:string)=>[...value.matchAll(/^\s*(\d{1,3})[.)]\s+/gm)].map(m=>m[1]);const beforeItems=itemNumbers(original),afterItems=itemNumbers(result);
      if(!result||result.split("\n").filter(x=>x.trim()).length<original.split("\n").filter(x=>x.trim()).length||beforeItems.length!==afterItems.length||beforeItems.some((n,i)=>n!==afterItems[i])||originalPrices.length!==newPrices.length||originalPrices.some((x,i)=>Number(x.slice(1).replace(/,/g,""))!==Number(newPrices[i].slice(1).replace(/,/g,""))))throw new Error("AI did not preserve all quotation items and prices. No changes were applied.");
      if(!controller.signal.aborted){setPreRubyScope(original);setScope(result);}
    }catch(e){if(!controller.signal.aborted)setAiError(e instanceof Error?e.message:"Could not tidy quotation");}
    finally{if(tidyRequest.current===controller){tidyRequest.current=null;setAiBusy(false);}}
  }
  return <div className="grid gap-5 xl:grid-cols-[1fr_380px]"><Card title={latest?"Edit quote":"Create quote"}><p className="mb-3 text-sm font-bold">Job title: {data.job.job_title||data.job.job_type||"Untitled job"}</p><form onSubmit={(e)=>void submit(e)} className="grid gap-4"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Field label="Quote amount"><MoneyField name="amount" defaultValue={latest?.amount??data.job.quoted_amount} required/></Field><Field label="VAT"><BmsSelect name="vat_rate" defaultValue={String(latest?.vat_rate??(config.businessDetails.vatRegistered?config.businessDetails.defaultVatRate:0))} className={inputClass}>{config.businessDetails.vatRegistered?<><option value="0">0% VAT</option><option value="5">5% VAT</option><option value="20">20% VAT</option></>:<option value="0">VAT not charged (not VAT registered)</option>}</BmsSelect></Field><Field label="Deposit required"><MoneyField name="deposit_amount" defaultValue={latest?.deposit_amount??(data.job.quoted_amount&&config.businessDetails.defaultDepositPercent?Number(data.job.quoted_amount)*config.businessDetails.defaultDepositPercent/100:undefined)}/></Field><Field label="Lead time"><BmsInput name="lead_time" value={leadTime} onChange={e=>setLeadTime(e.target.value)} maxLength={120} placeholder="e.g. 10 days, 3 weeks, 2 months" className={inputClass}/></Field><Field label="Valid until"><BmsInput name="valid_until" type="date" defaultValue={latest?.valid_until||new Date(Date.now()+config.businessDetails.quoteValidityDays*86400000).toISOString().slice(0,10)} className={inputClass}/></Field></div><details className="rounded-xl border border-black/10 bg-slate-50 p-3"><summary className="cursor-pointer text-xs font-semibold text-slate-600">Tenant quotation default lead time</summary><div className="mt-3 flex flex-wrap items-end gap-3"><label className="min-w-48 flex-1 text-xs font-semibold text-slate-700">Default for new quotes<BmsInput type="text" maxLength={120} value={defaultLeadTime} onChange={e=>setDefaultLeadTime(e.target.value)} className={inputClass}/></label><button type="button" disabled={savingDefault||!defaultLeadTime.trim()} onClick={()=>void saveLeadTimeDefault()} className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-xs font-bold disabled:opacity-40">Save tenant default</button></div><p className="mt-2 text-xs text-slate-500">Requires business settings permission. Existing quotation versions keep their original lead time.</p>{settingsMessage&&<p role="status" className="mt-2 text-xs">{settingsMessage}</p>}</details><div className="relative"><div className="mb-2 flex items-center justify-between gap-3"><span className="text-xs font-bold">Quotation wording</span>{config.ai.enabled&&config.ai.textAssist&&<><button type="button" form="not-a-quote-submit" disabled={aiBusy||quoteBusy} onClick={(e)=>{e.preventDefault();e.stopPropagation();void tidy();}} className="rounded-lg border border-black/15 bg-white px-3 py-1.5 text-xs font-black disabled:opacity-50">{aiBusy?"Ruby is tidying...":<><img src="https://res.cloudinary.com/ds3zepqin/image/upload/v1791154904/ruby-ai-business-assistant.webp" alt="" aria-hidden="true" className="mr-1.5 inline-block h-5 w-5 rounded-md object-cover align-middle"/>Tidy with Ruby</>}</button>{preRubyScope!==null&&<button type="button" disabled={aiBusy||quoteBusy} onClick={()=>{tidyRequest.current?.abort();setScope(preRubyScope);setPreRubyScope(null);setAiError("");}} className="rounded-lg border border-black/15 bg-white px-3 py-1.5 text-xs font-bold disabled:opacity-50" title="Restore quotation wording from before Ruby tidied it">Undo Ruby</button>}</>}</div><QuoteScopeEditor value={scope} onChange={value=>{setScope(value);setAiError("");}}/>{aiError&&<p className="mt-2 text-xs font-bold text-red-700">{aiError}</p>}</div><Field label="Quote Notes / exclusions (shown on quotation only)"><BmsTextarea name="exclusions" value={exclusions} onChange={e=>setExclusions(e.target.value)} className="min-h-24 w-full rounded-xl border border-black/15 p-3"/></Field><button disabled={quoteBusy} style={{backgroundColor:config.accentColour}} type="submit" className="justify-self-start rounded-xl px-5 py-2.5 text-sm font-black text-white disabled:opacity-50">{quoteBusy?"Saving quote...":latest?"Save quote":"Create quote"}</button>{saveResult&&<p role="status" className="text-sm font-semibold">{saveResult}</p>}</form></Card><Card title="Quote history">{data.quotes.length===0?<p className="text-sm text-black/50">No quote versions yet.</p>:<div className="space-y-3">{data.quotes.slice(0,5).map((q:any)=><div key={q.id} className="rounded-xl border border-black/10 p-3"><div className="flex justify-between"><b>Version {q.version}</b><div className="text-right"><b>{money(q.amount)}</b><div className="text-xs text-black/50">{q.created_at?new Date(q.created_at).toLocaleString("en-GB",{dateStyle:"medium",timeStyle:"short"}):""}</div></div></div><a href={`/admin/jobs/${reference}/quote/${q.id}`} target="_blank" style={{color:config.accentColour,textDecoration:"underline",textUnderlineOffset:"2px"}} className="mt-2 inline-block rounded-md border border-[var(--bms-accent)] px-3 py-2 text-sm font-black underline underline-offset-2 transition-colors hover:bg-[var(--bms-accent)] hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--bms-accent)]">Open quote</a></div>)}{data.quotes.length>5&&<details className="rounded-xl border border-black/10 p-3"><summary className="cursor-pointer text-sm font-bold">Show {data.quotes.length-5} older quotation versions</summary><div className="mt-3 space-y-3">{data.quotes.slice(5).map((q:any)=><div key={q.id} className="rounded-xl border border-black/10 p-3"><div className="flex justify-between"><b>Version {q.version}</b><div className="text-right"><b>{money(q.amount)}</b><div className="text-xs text-black/50">{q.created_at?new Date(q.created_at).toLocaleString("en-GB",{dateStyle:"medium",timeStyle:"short"}):""}</div></div></div><a href={`/admin/jobs/${reference}/quote/${q.id}`} target="_blank" rel="noopener noreferrer" style={{color:config.accentColour,textDecoration:"underline",textUnderlineOffset:"2px"}} className="mt-2 inline-block text-sm font-black">Open quote</a></div>)}</div></details>}</div>}</Card></div>}

function Costs({data,agreed,received,balance,grossProfit,reference,balanceActive,stopped,onAction,config,canPayments,canCosts}:{data:Bundle;agreed:number;received:number;balance:number;grossProfit:number;reference:string;balanceActive:boolean;stopped:boolean;onAction:(p:any)=>Promise<any>;config:CrmConfig;canPayments:boolean;canCosts:boolean}){async function payment(e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);await onAction({type:"payment",direction:text(fd,"direction"),payment_type:text(fd,"payment_type"),amount:num(fd,"amount"),payment_method:text(fd,"payment_method"),counterparty:text(fd,"counterparty"),paid_at:iso(fd.get("paid_at")),due_at:iso(fd.get("due_at")),notes:text(fd,"notes")});e.currentTarget.reset();}async function cost(e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);await onAction({type:"cost",category:text(fd,"category"),supplier:text(fd,"supplier"),estimated_amount:num(fd,"estimated_amount"),actual_amount:num(fd,"actual_amount"),paid_amount:num(fd,"paid_amount"),paid_at:iso(fd.get("paid_at")),due_at:iso(fd.get("due_at")),notes:text(fd,"notes")});e.currentTarget.reset();}async function material(e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);await onAction({type:"material_order",supplier_name:text(fd,"supplier_name"),description:text(fd,"description"),amount:num(fd,"amount"),ordered_at:iso(fd.get("ordered_at")),expected_at:iso(fd.get("expected_at")),notes:text(fd,"notes")});e.currentTarget.reset();}return <div className="grid gap-5 xl:grid-cols-2">{config.modules.payments&&canPayments&&<Card title="Customer payments"><div className="mb-4 grid grid-cols-3 gap-2 text-center"><Stat label="Final quote" value={money(agreed)}/><Stat label="Received" value={money(received)}/><Stat label="Outstanding" value={stopped?money(0):balanceActive?money(balance):"Not invoiced"}/></div><form onSubmit={(e)=>void payment(e)} className="grid gap-3 md:grid-cols-2"><Field label="Direction"><BmsSelect name="direction" className={inputClass}><option value="customer_in">Customer payment in</option><option value="subcontractor_out">Subcontractor payment out</option><option value="supplier_out">Supplier payment out</option>{config.modules.commission&&<option value="commission_out">Commission out</option>}</BmsSelect></Field><Field label="Type"><BmsInput name="payment_type" defaultValue="Payment" className={inputClass}/></Field><Field label="Amount"><MoneyField name="amount" required/></Field><Field label="Method"><BmsSelect name="payment_method" className={inputClass}><option>Bank transfer</option><option>Cash</option><option>Card</option><option>Other</option></BmsSelect></Field><Field label="Paid date"><BmsInput name="paid_at" type="datetime-local" className={inputClass}/></Field><Field label="Due date"><BmsInput name="due_at" type="datetime-local" className={inputClass}/></Field><Field label="Counterparty"><BmsInput name="counterparty" className={inputClass}/></Field><Field label="Notes"><BmsInput name="notes" className={inputClass}/></Field><Submit>Add payment</Submit></form><div className="mt-5 space-y-2">{data.payments.map((p:any)=><div key={p.id} className="flex justify-between gap-3 rounded-lg bg-[#f5f5f2] p-3 text-sm"><span>{p.payment_type}{p.paid_at?` · ${new Date(p.paid_at).toLocaleDateString("en-GB")}`:""}</span><b>{p.direction==="customer_in"?"+":"-"}{money(p.amount)}</b></div>)}</div></Card>}{config.modules.costs&&canCosts&&<Card title="Job costs & gross profit"><div className="mb-4 rounded-xl bg-[#f5f5f2] p-4"><p className="text-sm text-black/45">Gross profit from existing job cost entries</p><p className="mt-1 text-2xl font-black">{money(grossProfit)}</p></div><JobMaterialsProfit reference={reference} quotedGrossProfit={grossProfit} existingCosts={data.costs||[]}/><form onSubmit={(e)=>void cost(e)} className="grid gap-3 md:grid-cols-2"><Field label="Category"><BmsSelect name="category" className={inputClass}><option>Materials</option><option>Fabrication</option><option>Installation</option>{config.modules.commission&&<option>Commission</option>}<option>Automation equipment</option><option>Transport</option><option>Galvanising</option><option>Powder coating</option><option>Other</option></BmsSelect></Field><Field label="Supplier / person"><BmsInput name="supplier" className={inputClass}/></Field><Field label="Estimated"><MoneyField name="estimated_amount"/></Field><Field label="Actual / agreed"><MoneyField name="actual_amount"/></Field><Field label="Paid so far"><MoneyField name="paid_amount"/></Field><Field label="Paid date"><BmsInput name="paid_at" type="datetime-local" className={inputClass}/></Field><Field label="Due date"><BmsInput name="due_at" type="datetime-local" className={inputClass}/></Field><Field label="Notes"><BmsInput name="notes" className={inputClass}/></Field><Submit>Add cost</Submit></form><div className="mt-5 space-y-2">{data.costs.map((x:any)=><div key={x.id} className="flex justify-between rounded-lg bg-[#f5f5f2] p-3 text-sm"><span>{x.category}{x.supplier?` · ${x.supplier}`:""}</span><b>{money(x.actual_amount??x.estimated_amount)}</b></div>)}</div></Card>}{config.modules.costs&&canCosts&&<Card title="Materials / supplier orders" className="xl:col-span-2"><form onSubmit={(e)=>void material(e)} className="grid gap-3 md:grid-cols-3"><Field label="Supplier"><BmsInput name="supplier_name" className={inputClass}/></Field><Field label="Description"><BmsInput name="description" required className={inputClass}/></Field><Field label="Amount"><MoneyField name="amount"/></Field><Field label="Ordered"><BmsInput name="ordered_at" type="datetime-local" className={inputClass}/></Field><Field label="Expected"><BmsInput name="expected_at" type="datetime-local" className={inputClass}/></Field><Field label="Notes"><BmsInput name="notes" className={inputClass}/></Field><Submit>Add material order</Submit></form></Card>}</div>}

function Files({data,reference,reload,config}:{data:Bundle;reference:string;reload:()=>Promise<void>;config:CrmConfig}){const[busy,setBusy]=useState(false);const[error,setError]=useState("");async function upload(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;const form=e.currentTarget;setBusy(true);setError("");try{const fd=new FormData(form);const res=await fetch(`/api/admin/jobs/${encodeURIComponent(reference)}/files`,{method:"POST",body:fd});const body=await res.json().catch(()=>({}));if(!res.ok)throw Error(body.error||"Upload failed");await reload();form.reset();}catch(e){setError(e instanceof Error?e.message:"File upload failed. Try again.");}finally{setBusy(false);}}async function remove(id:string){if(busy||!window.confirm("Delete this file?"))return;setBusy(true);setError("");try{const res=await fetch(`/api/admin/jobs/${encodeURIComponent(reference)}/files?id=${encodeURIComponent(id)}`,{method:"DELETE"});const body=await res.json().catch(()=>({}));if(!res.ok)throw Error(body.error||"File could not be deleted");await reload();}catch(e){setError(e instanceof Error?e.message:"File deletion failed");}finally{setBusy(false);}}return <Card title="Photos & files"><form onSubmit={(e)=>void upload(e)} className="grid gap-3 rounded-2xl border-2 border-dashed border-black/15 p-5 md:grid-cols-[1fr_220px_auto]"><input name="file" type="file" required className="text-sm"/><BmsSelect name="category" className={inputClass}>{config.fileCategories.map(x=><option key={x} value={x.toLowerCase().replaceAll(" ","-")}>{x}</option>)}</BmsSelect><button disabled={busy} className="rounded-xl bg-[#141414] px-4 py-2 text-sm font-black text-white">{busy?"Uploading...":"Upload"}</button></form>{error&&<p role="alert" className="mt-3 text-sm text-red-700">{error}</p>}<div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{data.files.map((f:any)=><div key={f.id} className="rounded-xl border border-black/10 p-3"><p className="truncate font-bold">{f.file_name}</p><div className="mt-3 flex gap-3">{f.signed_url&&<a href={f.signed_url} target="_blank" rel="noopener noreferrer" className="text-sm font-black text-[var(--bms-accent)]">Open</a>}<button type="button" disabled={busy} onClick={()=>void remove(f.id)} className="text-sm font-bold text-red-700 disabled:opacity-50">Delete</button></div></div>)}</div></Card>}

function Workforce({data,reference,onAction,reload,canPayments,canCosts,config}:{data:Bundle;reference:string;onAction:(p:any)=>Promise<any>;reload:()=>Promise<void>;canPayments:boolean;canCosts:boolean;config:CrmConfig}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);const existing=text(fd,"subcontractor_id");await onAction({type:"subcontractor",subcontractor_id:existing,name:existing?null:text(fd,"name"),company:text(fd,"company"),phone:text(fd,"phone"),email:text(fd,"email"),capabilities:text(fd,"capabilities"),relationship_type:text(fd,"relationship_type"),assignment_role:text(fd,"assignment_role"),scope:text(fd,"scope"),agreed_cost:num(fd,"agreed_cost"),materials_included:fd.get("materials_included")==="on",scheduled_at:iso(fd.get("scheduled_at"))});e.currentTarget.reset();}const byId=new Map(data.subcontractors.map((s:any)=>[s.id,s]));async function pay(a:any,e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);const amount=Number(fd.get("amount")||0);if(!amount)return;await fetch(`/api/admin/jobs/${reference}/subcontractors/${a.id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({add_payment:amount,paid_at:iso(fd.get("paid_at")),counterparty:(byId.get(a.person_id||a.subcontractor_id) as any)?.name||null})});await reload();e.currentTarget.reset();}return <div className="grid gap-5 xl:grid-cols-[420px_1fr]"><Card title={`Assign ${config.workforceSingular}`}><form onSubmit={(e)=>void submit(e)} className="grid gap-3"><Field label="Existing person"><BmsSelect name="subcontractor_id" className={inputClass}><option value="">Add new person</option>{data.subcontractors.map((s:any)=><option key={s.id} value={s.id}>{s.name}{s.company?` · ${s.company}`:""} · {s.relationship_type==="employee"?"Employee":"Subcontractor"}</option>)}</BmsSelect></Field><div className="grid grid-cols-2 gap-3"><Field label="New name"><BmsInput name="name" className={inputClass}/></Field><Field label="Company"><BmsInput name="company" className={inputClass}/></Field><Field label="Phone"><BmsInput name="phone" className={inputClass}/></Field><Field label="Email"><BmsInput name="email" className={inputClass}/></Field></div><Field label="Employee or subcontractor"><BmsSelect name="relationship_type" className={inputClass}><option value="subcontractor">Subcontractor</option><option value="employee">Employee</option></BmsSelect></Field><Field label="Role"><BmsSelect name="assignment_role" className={inputClass}>{[...new Set([...(config.workforceRoles||[]),...(data.assignments||[]).map((a:any)=>String(a.assignment_role||"")).filter(Boolean)])].map(role=><option key={role} value={role}>{role.replaceAll("_"," ")}</option>)}</BmsSelect><a href="/settings#workforce-roles" className="mt-1 inline-block text-xs font-semibold text-[var(--bms-accent)]">Manage workforce roles in Settings</a></Field><Field label="Capabilities"><BmsInput name="capabilities" placeholder="Fabrication, installation, automation..." className={inputClass}/></Field><Field label="Scope on this job"><BmsInput name="scope" className={inputClass}/></Field>{canCosts&&<Field label="Agreed cost"><MoneyField name="agreed_cost"/></Field>}<Field label="Scheduled"><BmsInput name="scheduled_at" type="datetime-local" className={inputClass}/></Field><label className="text-sm font-bold"><input name="materials_included" type="checkbox" className="mr-2"/>Materials included</label><Submit>Assign</Submit></form></Card><Card title="Assigned people">{data.assignments.length===0?<p className="text-sm text-black/50">Nobody assigned yet.</p>:<div className="space-y-3">{data.assignments.map((a:any)=>{const s=byId.get(a.person_id||a.subcontractor_id) as any;const isEmployee=s?.relationship_type==="employee";const outstanding=Math.max(0,Number(a.agreed_cost||0)-Number(a.paid_amount||0));return <div key={a.id} className="rounded-xl border border-black/10 p-4"><div className="flex flex-wrap justify-between gap-3"><div><p className="font-black">{s?.name||"Person"}</p><p className="text-xs text-black/45">{String(a.assignment_role||"subcontractor").replaceAll("_"," ")} · {isEmployee?"Employee":"Subcontractor"}</p><p className="mt-1 text-sm text-black/50">{a.scope||"Scope not specified"}</p></div>{canCosts&&!isEmployee&&<div className="text-right"><b>{money(a.agreed_cost)}</b><p className="text-xs text-[var(--bms-accent)]">{money(outstanding)} outstanding</p></div>}</div>{canCosts&&canPayments&&!isEmployee&&outstanding>0&&<form onSubmit={(e)=>void pay(a,e)} className="mt-3 grid gap-2 sm:grid-cols-[1fr_1fr_auto]"><MoneyField name="amount"/><BmsInput name="paid_at" type="datetime-local" className={inputClass}/><button className="rounded-xl border border-black/15 px-3 text-sm font-bold">Record payment</button></form>}</div>})}</div>}</Card></div>}
